# =========================================================
# DB HELPERS
# =========================================================

def add_user(user_id):
    with db_lock:
        cur.execute("INSERT OR IGNORE INTO users (user_id, balance) VALUES (?, 0)", (user_id,))
        conn.commit()

def get_balance(user_id):
    add_user(user_id)
    with db_lock:
        cur.execute("SELECT balance FROM users WHERE user_id=?", (user_id,))
        row = cur.fetchone()
    return float(row[0]) if row else 0

def change_balance(user_id, amount):
    add_user(user_id)
    with db_lock:
        cur.execute("UPDATE users SET balance = balance + ? WHERE user_id=?", (amount, user_id))
        conn.commit()

def get_all_users():
    with db_lock:
        cur.execute("SELECT user_id FROM users")
        return [row[0] for row in cur.fetchall()]

def is_moderator(user_id):
    with db_lock:
        cur.execute("SELECT user_id FROM moderators WHERE user_id=?", (user_id,))
        return cur.fetchone() is not None

def add_moderator(user_id, admin_id):
    with db_lock:
        cur.execute("INSERT OR IGNORE INTO moderators (user_id, added_by, added_at) VALUES (?, ?, ?)",
                   (user_id, admin_id, int(time.time())))
        conn.commit()

def remove_mod(user_id):
    with db_lock:
        cur.execute("DELETE FROM moderators WHERE user_id=?", (user_id,))
        conn.commit()

def get_moderators():
    with db_lock:
        cur.execute("SELECT user_id, added_at FROM moderators ORDER BY added_at DESC")
        return cur.fetchall()

