def lzt_get(endpoint, params=None):
    url = f"{LZT_API_BASE.rstrip('/')}/{endpoint.lstrip('/')}"
    headers = {
        "Authorization": f"Bearer {LZT_API_TOKEN}",
        "Accept": "application/json",
    }
    try:
        r = requests.get(url, headers=headers, params=params or {}, timeout=25)
        r.raise_for_status()
        return r.json()
    except Exception as e:
        logger.error(f"LZT GET error [{endpoint}]: {e}")
        return None

def lzt_post(endpoint, params=None):
    url = f"{LZT_API_BASE.rstrip('/')}/{endpoint.lstrip('/')}"
    headers = {
        "Authorization": f"Bearer {LZT_API_TOKEN}",
        "Accept": "application/json",
    }
    try:
        r = requests.post(url, headers=headers, params=params or {}, timeout=25)
        return r.json()
    except Exception as e:
        logger.error(f"LZT POST error [{endpoint}]: {e}")
        return None

LZT_LAST_ERROR = ""

def lzt_search(country_code, pmin, pmax):
    """Поиск аккаунтов. ТОЛЬКО строгие фильтры, без запасных «мягких» запросов:
    без спамблока, без гео-спамблока, без фишинга/стилеров/брута/перепродажи."""
    global LZT_LAST_ERROR
    LZT_LAST_ERROR = ""
    params = [
        ("pmin",                pmin),
        ("pmax",                pmax),
        ("country[]",           country_code),
        ("spam",                "no"),
        ("allow_geo_spamblock", "false"),
        ("order_by",            "price_to_up"),
        ("currency",            "rub"),
        ("not_origin[]",        "phishing"),
        ("not_origin[]",        "stealer"),
        ("not_origin[]",        "brute"),
        ("not_origin[]",        "resale"),
    ]
    url = f"{LZT_API_BASE.rstrip('/')}/telegram"
    headers = {
        "Authorization": f"Bearer {LZT_API_TOKEN}",
        "Accept": "application/json",
    }
    try:
        r = requests.get(url, headers=headers, params=params, timeout=25)
        if r.status_code != 200:
            LZT_LAST_ERROR = f"HTTP {r.status_code}: {r.text[:400]}"
            logger.error(f"LZT search {LZT_LAST_ERROR}")
            return None
        data = r.json()
        if isinstance(data, dict) and data.get("items"):
            return data
        LZT_LAST_ERROR = f"HTTP 200, items пусто: {str(data)[:300]}"
    except Exception as e:
        LZT_LAST_ERROR = f"исключение: {e}"
        logger.error(f"LZT search error: {e}")
    return None

def lzt_check(item_id):
    return lzt_post(f"/{item_id}/check-account")

def lzt_check_ok(res):
    """Аккаунт валиден, если LZT не вернул ошибок и отдал item (или явный ok/valid)."""
    if not res or not isinstance(res, dict):
        return False
    if res.get("errors") or res.get("error"):
        return False
    return bool(res.get("item")) or res.get("status") == "ok" or res.get("valid") is True

def lzt_get_all_balance_ids():
    res = lzt_get("/me")
    if not res or "user" not in res:
        return [None]
    user = res["user"]
    balance_ids = []
    if float(user.get("balance") or 0) > 0:
        balance_ids.append(None)
    for b in user.get("balances", []):
        val = float(b.get("balance") or b.get("convertedBalance") or 0)
        bid = b.get("id")
        if val > 0 and bid:
            balance_ids.append(bid)
    if not balance_ids:
        balance_ids.append(None)
    return balance_ids

def lzt_buy(item_id, price):
    """Покупка с перебором балансов."""
    balance_ids = lzt_get_all_balance_ids()
    last = None
    for bid in balance_ids:
        params = {"price": price} if bid is None else {"price": price, "balance_id": bid}
        res = lzt_post(f"/{item_id}/fast-buy", params=params)
        last = res
        if not res:
            continue
        if not res.get("errors") and not res.get("error"):
            return res
        err = str(res.get("errors") or res.get("error") or "")
        if not any(w in err.lower() for w in ("balance", "недостаточно", "insufficient", "not enough", "funds")):
            return res
        logger.warning(f"lzt_buy #{item_id} balance_id={bid}: {err} — следующий баланс")
    return last

def lzt_get_phone(item_id):
    """Получить номер телефона аккаунта."""
    def fmt(p):
        if not p:
            return ""
        clean = re.sub(r'[^\d+]', '', str(p))
        if clean and not clean.startswith('+'):
            clean = '+' + clean
        return clean

    res = lzt_get(f"/{item_id}")
    if res and isinstance(res, dict):
        item = res.get('item', {})
        if isinstance(item, dict):
            ph = item.get('telegram_phone')
            if ph:
                return fmt(ph)
            login_data = item.get('loginData', {})
            if isinstance(login_data, dict):
                login = login_data.get('login')
                if login and re.match(r'^\+?\d{7,15}$', str(login)):
                    return fmt(login)

    res2 = lzt_post(f"/{item_id}/goods/phone")
    if res2 and isinstance(res2, dict):
        ph = res2.get('phone') or res2.get('number')
        if ph:
            return fmt(ph)
    return None

def get_lzt_balance():
    res = lzt_get("/me")
    if not res or "user" not in res:
        return None
    user = res["user"]
    main_balance = float(user.get("balance") or 0)
    extra = []
    for b in user.get("balances", []):
        val = float(b.get("balance") or b.get("convertedBalance") or 0)
        title = b.get("title") or b.get("custom_title") or f"Баланс #{b.get('balance_id','')}"
        extra.append((title, val))
    return {"main": main_balance, "extra": extra}

def is_clean_account(item: dict) -> bool:
    """Вторая линия защиты (на случай если API проигнорировал фильтр):
    отсеивает плохое происхождение, спамблок и гео-блок."""
    bad_origin = {"phishing", "stealer", "brute", "resale"}
    origin = str(item.get("origin") or "").lower()
    if origin in bad_origin:
        return False
    if origin and origin not in {"autoreg", "personal"}:
        return False
    truthy = (1, True, "1", "yes", "true", "True", "Yes")
    for key, val in item.items():
        k = str(key).lower()
        if ("spam" in k or "geo" in k) and val in truthy:
            logger.warning(f"item {item.get('item_id')} отсеян: {key}={val}")
            return False
    return True

