def crypto_api(method, data=None):
    url = f"https://pay.crypt.bot/api/{method}"
    headers = {"Crypto-Pay-API-Token": CRYPTO_PAY_TOKEN}
    try:
        response = requests.post(url, headers=headers, json=data or {}, timeout=20)
        result = response.json()
        if result.get("ok"):
            return result.get("result")
    except Exception as e:
        logger.error(f"Crypto Pay error: {e}")
    return None

