def _custom_emoji_button(text, callback_data, emoji_id):
    try:
        # Новые версии pyTelegramBotAPI передают это поле напрямую в Bot API.
        return types.InlineKeyboardButton(
            text=text,
            callback_data=callback_data,
            icon_custom_emoji_id=str(emoji_id)
        )
    except TypeError:
        # Совместимость со старыми версиями библиотеки.
        # В этом случае нужно обновить pyTelegramBotAPI.
        btn = types.InlineKeyboardButton(text=text, callback_data=callback_data)
        try:
            btn.icon_custom_emoji_id = str(emoji_id)
        except Exception:
            pass
        return btn

