def catalog_keyboard(page=0, cheapest=False):
    """Клавиатура каталога Telegram аккаунтов — по 8 стран на страницу."""
    keys = list(CATALOG.keys())
    if cheapest:
        keys.sort(key=lambda k: CATALOG[k][5])
    per_page = 8
    start = page * per_page
    end = start + per_page
    page_keys = keys[start:end]
    total_pages = (len(keys) + per_page - 1) // per_page

    kb = types.InlineKeyboardMarkup(row_width=2)
    row = []
    for k in page_keys:
        flag, name, prefix, _, _, our_price, _ = CATALOG[k]
        row.append(types.InlineKeyboardButton(
            f"{flag} {name}  •  {our_price} ₽", callback_data=f"tg_buy:{k}"
        ))
        if len(row) == 2:
            kb.row(*row)
            row = []
    if row:
        kb.row(*row)

    nav = []
    if page > 0:
        nav.append(types.InlineKeyboardButton("◀️", callback_data=f"tg_cheap_page:{page-1}" if cheapest else f"tg_page:{page-1}"))
    nav.append(types.InlineKeyboardButton(f"{page+1}/{total_pages}", callback_data="noop"))
    if end < len(keys):
        nav.append(types.InlineKeyboardButton("▶️", callback_data=f"tg_cheap_page:{page+1}" if cheapest else f"tg_page:{page+1}"))
    if nav:
        kb.row(*nav)

    if not cheapest:
        kb.add(types.InlineKeyboardButton("💸 Самые дешёвые", callback_data="tg_cheapest"))
    else:
        kb.add(types.InlineKeyboardButton("📋 Все аккаунты", callback_data="tg_accounts"))
    kb.add(types.InlineKeyboardButton("🔍 Поиск", callback_data="tg_search"))
    kb.add(types.InlineKeyboardButton("◀️ Главное меню", callback_data="home"))
    return kb

