def _process_case_purchase(user_id, chat_id, message_id, case_key):
    """Открытие кейса: списывает цену, выбирает случайный приз (с учётом весов) и
    ставит заказ в очередь на ручную выдачу администратором (без автовыдачи)."""
    case_emoji, case_name, case_price, prizes = CASES[case_key]
    countries = [c for c, w in prizes]
    weights = [w for c, w in prizes]
    country_key = random.choices(countries, weights=weights, k=1)[0]
    flag, name, prefix, pmin, pmax, our_price, lolz_country = get_country_info(country_key)

    kb_home = types.InlineKeyboardMarkup()
    kb_home.add(types.InlineKeyboardButton("◀️ Главное меню", callback_data="home"))

    def send_err(text):
        try:
            bot.send_message(chat_id, text, reply_markup=kb_home)
        except:
            pass

    # Списываем баланс и создаём заказ, ожидающий ручной выдачи
    with db_lock:
        cur.execute("UPDATE users SET balance = balance - ? WHERE user_id=? AND balance >= ?",
                    (case_price, user_id, case_price))
        if cur.rowcount != 1:
            conn.rollback()
            send_err("❌ Недостаточно средств или ошибка списания.")
            return
        cur.execute("""INSERT INTO orders
            (user_id, product_id, item_id, price, status, created, country_key, lolz_item_id, phone)
            VALUES (?, 0, 0, ?, 'pending', ?, ?, '', '')""",
            (user_id, case_price, int(time.time()), country_key))
        order_id = cur.lastrowid
        conn.commit()

    kb_result = types.InlineKeyboardMarkup()
    kb_result.add(types.InlineKeyboardButton("📋 Мои заказы", callback_data="orders"))
    kb_result.add(types.InlineKeyboardButton("🆘 Поддержка", callback_data="support"))
    kb_result.add(types.InlineKeyboardButton("◀️ Главное меню", callback_data="home"))

    new_bal = get_balance(user_id)
    try:
        anim = bot.send_message(chat_id, f"{case_emoji} <b>Открываем Mystery Box «{case_name}»...</b>")
        time.sleep(0.8)
        bot.edit_message_text(
            "🎉 <b>Приз выпал!</b>",
            chat_id, anim.message_id
        )
        time.sleep(0.5)
        bot.delete_message(chat_id, anim.message_id)
    except Exception:
        pass

    bot.send_message(
        chat_id,
        f"🎁 <b>Mystery Box «{case_name}» открыт!</b>\n\n"
        f"🌍 Приз: <b>{flag} {name}</b>\n"
        f"📦 Заказ: <b>#{order_id}</b>\n\n"
        f"💸 Потрачено: <b>{case_price} ₽</b>\n"
        f"💳 Остаток: <b>{new_bal:.2f} ₽</b>\n\n"
        f"⏳ Аккаунт выдаст администратор вручную, ожидайте.",
        reply_markup=kb_result
    )

    # Уведомление админу о призе из кейса — для ручной выдачи
    try:
        username = f"@{bot.get_chat(user_id).username}" if bot.get_chat(user_id).username else f"ID {user_id}"
        bot.send_message(
            ADMIN_ID,
            f"🎰 <b>Призы рандом · Mystery Box «{case_name}» #{order_id}</b>\n\n"
            f"👤 {username} (ID {user_id})\n"
            f"🌍 Выпало: {flag} {name}\n"
            f"💰 Оплачено: {case_price} ₽\n\n"
            f"⚠️ Требуется ручная выдача аккаунта."
        )
    except:
        pass

