@bot.callback_query_handler(func=lambda call: call.data.startswith("sms:"))
def get_sms(call):
    item_id = call.data.split(":")[1]
    bot.answer_callback_query(call.id, "⏳ Запрашиваем код...")

    def fetch_sms():
        res = lzt_get(f"/{item_id}/telegram-login-code")
        code = None
        if res and isinstance(res, dict):
            codes = res.get('codes')
            if codes and isinstance(codes, list) and len(codes) > 0:
                first = codes[0]
                if isinstance(first, dict) and 'code' in first:
                    code = str(first['code'])
            if not code:
                code = str(res.get('code') or res.get('login_code') or '')

        kb = types.InlineKeyboardMarkup()
        kb.add(types.InlineKeyboardButton("🔄 Обновить код", callback_data=f"sms:{item_id}"))
        kb.add(types.InlineKeyboardButton("◀️ Главное меню", callback_data="home"))

        if code:
            bot.send_message(call.message.chat.id,
                f"📱 <b>Код входа в Telegram:</b>\n\n"
                f"<code>{code}</code>\n\n"
                f"Используйте его для входа в аккаунт.",
                reply_markup=kb)
        else:
            bot.send_message(call.message.chat.id,
                "⏳ Код ещё не пришёл. Запросите вход в аккаунт и попробуйте снова.",
                reply_markup=kb)

    threading.Thread(target=fetch_sms, daemon=True).start()

