def get_user_promo(user_id):
    with db_lock:
        cur.execute("""
            SELECT u.promo_code, p.discount_percent, p.active, p.max_uses, p.used_count
            FROM users u
            LEFT JOIN promo_codes p ON UPPER(u.promo_code)=p.code
            WHERE u.user_id=?
        """, (user_id,))
        row = cur.fetchone()
    if not row or not row[0] or row[2] != 1:
        return None
    if row[3] and row[4] >= row[3]:
        return None
    return {"code": row[0], "discount": float(row[1])}

@bot.callback_query_handler(func=lambda call: call.data == "promo_enter")
def promo_enter(call):
    bot.answer_callback_query(call.id)
    msg = bot.send_message(
        call.message.chat.id,
        "🎟 <b>Промокод</b>\n\n"
        "Введите промокод для скидки на следующий аккаунт.\n"
        "Если промокод уже активирован, новый заменит его.",
        parse_mode="HTML"
    )
    bot.register_next_step_handler(msg, process_promo_code)

def process_promo_code(message):
    user_id = message.from_user.id
    code = (message.text or "").strip().upper()
    if not re.fullmatch(r"[A-ZА-ЯЁ0-9_-]{3,32}", code):
        bot.send_message(user_id, "❌ Некорректный промокод.")
        return
    with db_lock:
        cur.execute("""
            SELECT code, discount_percent, max_uses, used_count, active
            FROM promo_codes WHERE code=?
        """, (code,))
        row = cur.fetchone()
        cur.execute("SELECT 1 FROM promo_uses WHERE code=? AND user_id=?", (code, user_id))
        already_used = cur.fetchone() is not None

    if not row or row[4] != 1:
        bot.send_message(user_id, "❌ Промокод не найден или отключён.")
        return
    if row[2] and row[3] >= row[2]:
        bot.send_message(user_id, "❌ Лимит активаций этого промокода исчерпан.")
        return
    if already_used:
        bot.send_message(user_id, "❌ Вы уже использовали этот промокод.")
        return

    with db_lock:
        cur.execute("UPDATE users SET promo_code=? WHERE user_id=?", (code, user_id))
        conn.commit()
    bot.send_message(
        user_id,
        f"✅ <b>Промокод активирован!</b>\n\n"
        f"🎟 <code>{code}</code>\n"
        f"💸 Скидка: <b>{float(row[1]):g}%</b>\n\n"
        f"Скидка применится к следующей покупке аккаунта.",
        parse_mode="HTML",
        reply_markup=main_menu()
    )

