def _doc_pages(text, limit=3800):
    paragraphs = text.split("\n\n")
    pages=[]
    cur=""
    for para in paragraphs:
        candidate = para if not cur else cur + "\n\n" + para
        if len(candidate) <= limit:
            cur=candidate
        else:
            if cur:
                pages.append(cur)
            # Extremely long paragraph fallback.
            while len(para) > limit:
                cut=para.rfind("\n",0,limit)
                if cut < 100:
                    cut=limit
                pages.append(para[:cut])
                para=para[cut:].lstrip()
            cur=para
    if cur:
        pages.append(cur)
    return pages

