def process_custom_stars_amount(message):
    user_id = message.from_user.id
    raw = (message.text or "").strip().replace(" ", "").replace(",", ".")
    try:
        value = float(raw)
        if not value.is_integer():
            raise ValueError
        amount = int(value)
    except ValueError:
        bot.send_message(user_id, "❌ Введите целое количество звёзд, например: 750")
        return
    if amount < MIN_DEPOSIT_STARS:
        bot.send_message(user_id, f"❌ Минимум — {MIN_DEPOSIT_STARS} ⭐.")
        return
    if amount > 1000000:
        bot.send_message(user_id, "❌ Максимальная сумма — 1 000 000 ⭐.")
        return

    payload = f"stars:{user_id}:{amount}:{int(time.time())}"
    try:
        bot.send_invoice(
            chat_id=user_id,
            title="Пополнение баланса",
            description=f"Пополнение на {amount} ⭐",
            invoice_payload=payload,
            provider_token="",
            currency="XTR",
            prices=[types.LabeledPrice(label=f"Пополнение {amount} ⭐", amount=amount)]
        )
    except Exception as e:
        logger.error(f"Stars custom invoice error: {e}")
        bot.send_message(user_id, "❌ Не удалось создать счёт. Попробуйте ещё раз.")

