def process_custom_sbp_amount(message):
    user_id = message.from_user.id
    raw = (message.text or "").strip().replace(" ", "").replace(",", ".")
    try:
        value = float(raw)
    except ValueError:
        bot.send_message(user_id, "❌ Введите сумму числом, например: 750")
        return
    if not value.is_integer():
        bot.send_message(user_id, "❌ Сумма должна быть целым числом рублей.")
        return
    amount = int(value)
    if amount < MIN_DEPOSIT_SBP:
        bot.send_message(user_id, f"❌ Минимальная сумма — {MIN_DEPOSIT_SBP} ₽.")
        return
    if amount > 1000000:
        bot.send_message(user_id, "❌ Максимальная сумма — 1 000 000 ₽.")
        return
    invoice = platega_create_sbp(user_id, amount)
    if not invoice or not invoice.get("id") or not invoice.get("url"):
        bot.send_message(user_id, "❌ Не удалось создать счёт в Platega.io. Попробуйте ещё раз.")
        return
    payment_id = invoice["id"]
    with db_lock:
        cur.execute("INSERT OR IGNORE INTO payments (user_id, payment_id, amount, currency, status, created) VALUES (?, ?, ?, ?, ?, ?)",
                    (user_id, payment_id, amount, PLATEGA_CURRENCY, "pending", int(time.time())))
        conn.commit()
    kb = types.InlineKeyboardMarkup(row_width=1)
    kb.add(types.InlineKeyboardButton("💳 Оплатить через СБП", url=invoice["url"]))
    kb.add(types.InlineKeyboardButton("🔄 Проверить оплату", callback_data=f"check_sbp:{payment_id}"))
    kb.add(types.InlineKeyboardButton("◀️ Назад", callback_data="deposit"))
    bot.send_message(
        user_id,
        f"💳 <b>Счёт создан</b>\n\nСумма: <b>{amount} ₽</b>\n\nНажмите «Оплатить через СБП», завершите оплату и затем нажмите «Проверить оплату»." ,
        parse_mode="HTML", reply_markup=kb
    )

