@bot.callback_query_handler(func=lambda call: call.data.startswith("check_sbp:"))
def check_sbp(call):
    transaction_id = call.data.split(":", 1)[1]
    user_id = call.from_user.id
    result = platega_api("GET", f"/transaction/{transaction_id}")
    if not result or not isinstance(result, dict):
        bot.answer_callback_query(call.id, "❌ Не удалось проверить платёж.", show_alert=True)
        return
    # Platega возвращает статус в верхнем регистре: PENDING / CONFIRMED / CANCELED / CHARGEBACKED
    status = str(result.get("status") or "").upper()
    if status in {"CANCELED", "CHARGEBACKED"}:
        bot.answer_callback_query(call.id, "❌ Платёж отменён или возвращён.", show_alert=True)
        return
    if status != "CONFIRMED":
        bot.answer_callback_query(call.id, f"⏳ Статус: {status or 'ожидание оплаты'}", show_alert=True)
        return
    with db_lock:
        cur.execute("SELECT user_id, amount, status FROM payments WHERE payment_id=?", (transaction_id,))
        row = cur.fetchone()
        if not row:
            bot.answer_callback_query(call.id, "❌ Платёж не найден.", show_alert=True)
            return
        db_user_id, amount, db_status = row
        if int(db_user_id) != int(user_id):
            bot.answer_callback_query(call.id, "❌ Платёж принадлежит другому пользователю.", show_alert=True)
            return
        if db_status == "paid":
            bot.answer_callback_query(call.id, "✅ Уже зачислено.", show_alert=True)
            return
        cur.execute("UPDATE payments SET status='paid' WHERE payment_id=?", (transaction_id,))
        conn.commit()
    change_balance(user_id, float(amount))
    bot.answer_callback_query(call.id, "✅ Оплата подтверждена!")
    bot.send_message(user_id,
        f"✅ <b>Оплата получена!</b>\n\n💳 СБП: <b>{float(amount):.2f} ₽</b> зачислено\n💰 Баланс: <b>{get_balance(user_id):.2f} ₽</b>",
        parse_mode="HTML", reply_markup=main_menu())

