@bot.callback_query_handler(func=lambda call: call.data.startswith("review:"))
def review_start(call):
    try:
        order_id = int(call.data.split(":", 1)[1])
    except (ValueError, IndexError):
        bot.answer_callback_query(call.id, "❌ Некорректный заказ", show_alert=True)
        return

    user_id = call.from_user.id
    with db_lock:
        cur.execute("""
            SELECT id, status, country_key, phone
            FROM orders
            WHERE id=? AND user_id=?
        """, (order_id, user_id))
        row = cur.fetchone()

    if not row:
        bot.answer_callback_query(call.id, "❌ Заказ не найден", show_alert=True)
        return

    oid, status, country_key, phone = row
    if status != "completed":
        bot.answer_callback_query(call.id, "❌ Отзыв доступен только после покупки", show_alert=True)
        return

    # Не даём повторно открывать форму отзыва, пока пользователь пишет текущий отзыв.
    review_state[user_id] = {
        "order_id": oid,
        "chat_id": call.message.chat.id
    }

    bot.answer_callback_query(call.id)
    bot.send_message(
        call.message.chat.id,
        f"⭐ <b>Отзыв по заказу #{oid}</b>\n\n"
        "Напишите ваш отзыв одним сообщением. Он автоматически будет отправлен администратору.\n\n"
        "Для отмены отправьте: <code>ОТМЕНА</code>"
    )


@bot.message_handler(func=lambda m: m.from_user.id in review_state and bool(m.text))
def review_receive(message):
    user_id = message.from_user.id
    state = review_state.get(user_id)
    if not state:
        return

    if message.text.strip().upper() == "ОТМЕНА":
        review_state.pop(user_id, None)
        bot.send_message(message.chat.id, "❌ Отзыв отменён.", reply_markup=main_menu())
        return

    order_id = state["order_id"]
    review_text = message.text.strip()
    if not review_text:
        bot.reply_to(message, "❌ Отзыв не может быть пустым.")
        return

    with db_lock:
        cur.execute("""
            SELECT id, status, country_key, phone
            FROM orders
            WHERE id=? AND user_id=?
        """, (order_id, user_id))
        row = cur.fetchone()

        if not row or row[1] != "completed":
            review_state.pop(user_id, None)
            bot.send_message(message.chat.id, "❌ Заказ не найден или уже недоступен.")
            return

        cur.execute(
            "INSERT INTO reviews (user_id, order_id, review_text, created) VALUES (?, ?, ?, ?)",
            (user_id, order_id, review_text, int(time.time()))
        )
        conn.commit()

    review_state.pop(user_id, None)

    try:
        # Пересылаем администратору именно сообщение покупателя с отзывом.
        bot.forward_message(ADMIN_ID, message.chat.id, message.message_id)
        bot.send_message(
            ADMIN_ID,
            f"⭐ <b>Новый отзыв</b>\n"
            f"👤 Пользователь: <code>{user_id}</code>\n"
            f"📦 Заказ: <code>#{order_id}</code>"
        )
    except Exception as e:
        logger.error(f"Не удалось отправить отзыв админу: {e}")

    bot.send_message(
        message.chat.id,
        "✅ <b>Спасибо за отзыв!</b>\n\n"
        "Ваш отзыв автоматически отправлен администратору.",
        reply_markup=main_menu()
    )

