@bot.callback_query_handler(func=lambda call: call.data == "orders")
def orders(call):
    user_id = call.from_user.id
    with db_lock:
        cur.execute("""
            SELECT o.id, o.price, o.status, o.created, o.country_key, o.phone, o.lolz_item_id
            FROM orders o
            WHERE o.user_id=?
            ORDER BY o.id DESC LIMIT 20
        """, (user_id,))
        rows = cur.fetchall()

    if not rows:
        text = "📋 <b>Заказов пока нет.</b>"
    else:
        text = "📋 <b>Мои заказы</b>\n\n"
        for oid, price, status, created, country_key, phone, item_id in rows:
            status_e = {"pending": "⏳", "completed": "✅", "rejected": "❌", "refunded": "↩️"}.get(status, "❓")
            date = time.strftime("%d.%m %H:%M", time.localtime(created))
            if country_key and get_country_info(country_key):
                flag, name, prefix, *_ = get_country_info(country_key)
                item_label = f"{flag} TG {name}"
            else:
                item_label = "Telegram аккаунт"

            text += f"{status_e} #{oid} | {date}\n📦 {item_label}\n💰 {price:.2f} ₽"
            if phone:
                text += f"\n📱 <code>{phone}</code>"
            if status == "completed" and item_id:
                text += f"\n🔑 Получить SMS: кнопка ниже"
                text += "\n\n"
            else:
                text += "\n\n"

    kb = types.InlineKeyboardMarkup(row_width=1)

    # Отдельные кнопки для каждого завершённого заказа.
    for oid, price, status, created, country_key, phone, item_id in rows:
        if status == "completed":
            if item_id:
                kb.add(types.InlineKeyboardButton(
                    f"📱 SMS · Заказ #{oid}", callback_data=f"sms:{item_id}"
                ))
            kb.add(types.InlineKeyboardButton(
                f"📤 Передать · Заказ #{oid}", callback_data=f"transfer:{oid}"
            ))
            kb.add(types.InlineKeyboardButton(
                f"⭐ Отзыв · Заказ #{oid}", callback_data=f"review:{oid}"
            ))

    kb.add(types.InlineKeyboardButton("◀️ Назад", callback_data="home"))

    try:
        bot.edit_message_text(text, call.message.chat.id, call.message.message_id, reply_markup=kb)
    except:
        bot.send_message(call.message.chat.id, text, reply_markup=kb)

