@bot.message_handler(func=lambda m: m.from_user.id in transfer_state and bool(m.text))
def transfer_receive(m):
    sender_id = m.from_user.id
    state = transfer_state.get(sender_id)
    if not state:
        return

    raw_target = m.text.strip()
    if not raw_target:
        bot.reply_to(m, "❌ Введите @username или Telegram ID.")
        return

    target_ref = raw_target
    if raw_target.startswith("@"):
        target_ref = raw_target
    elif raw_target.isdigit():
        target_ref = int(raw_target)
    else:
        bot.reply_to(m, "❌ Формат не распознан. Пример: @username или 123456789.")
        return

    order_id = state["order_id"]

    with db_lock:
        cur.execute("""
            SELECT id, user_id, status, country_key, phone, lolz_item_id
            FROM orders
            WHERE id=?
        """, (order_id,))
        row = cur.fetchone()

    if not row:
        transfer_state.pop(sender_id, None)
        bot.send_message(sender_id, "❌ Заказ не найден.", reply_markup=main_menu())
        return

    oid, owner_id, status, country_key, phone, item_id = row
    if owner_id != sender_id or status != "completed":
        transfer_state.pop(sender_id, None)
        bot.send_message(sender_id, "❌ Этот заказ больше нельзя передать.", reply_markup=main_menu())
        return

    try:
        target_chat = bot.get_chat(target_ref)
        target_id = target_chat.id
        target_username = f"@{target_chat.username}" if target_chat.username else f"ID {target_id}"
    except Exception:
        bot.send_message(
            sender_id,
            "❌ Не удалось найти получателя.\n\n"
            "Проверьте @username/ID и убедитесь, что получатель уже запускал бота через /start."
        )
        return

    if target_id == sender_id:
        bot.send_message(sender_id, "❌ Нельзя передать аккаунт самому себе.")
        return

    # Данные страны для красивого сообщения.
    if get_country_info(country_key):
        flag, name, prefix, *_ = get_country_info(country_key)
        item_label = f"{flag} {name}"
    else:
        item_label = "Telegram аккаунт"

    recipient_kb = types.InlineKeyboardMarkup(row_width=1)
    if item_id:
        recipient_kb.add(
            types.InlineKeyboardButton("📱 Получить SMS код", callback_data=f"sms:{item_id}")
        )
    recipient_kb.add(types.InlineKeyboardButton("📋 Мои заказы", callback_data="orders"))

    # Сначала убеждаемся, что получатель доступен для сообщения.
    try:
        bot.send_message(
            target_id,
            "🎁 <b>Вам передали Telegram-аккаунт!</b>\n\n"
            f"📦 Страна: <b>{item_label}</b>\n"
            f"📱 Номер: <code>{phone or 'не указан'}</code>\n\n"
            "Теперь этот заказ находится в вашем списке покупок.",
            reply_markup=recipient_kb
        )
    except Exception as e:
        logger.warning(f"Не удалось уведомить получателя {target_id}: {e}")
        bot.send_message(
            sender_id,
            "❌ Не удалось отправить сообщение получателю.\n"
            "Пусть он сначала откроет бота и нажмёт /start, затем повторите передачу."
        )
        return

    # Меняем владельца заказа.
    try:
        with db_lock:
            cur.execute("""
                UPDATE orders
                SET user_id=?
                WHERE id=? AND user_id=? AND status='completed'
            """, (target_id, order_id, sender_id))

            if cur.rowcount != 1:
                conn.rollback()
                bot.send_message(sender_id, "❌ Передача не выполнена: заказ уже изменён.")
                return

            conn.commit()
    except Exception as e:
        logger.error(f"Ошибка передачи заказа #{order_id}: {e}")
        bot.send_message(sender_id, "❌ Ошибка при передаче. Попробуйте ещё раз.")
        return

    transfer_state.pop(sender_id, None)

    bot.send_message(
        sender_id,
        "✅ <b>Аккаунт передан!</b>\n\n"
        f"📦 Заказ: <b>#{order_id}</b>\n"
        f"👤 Получатель: <b>{target_username}</b>\n\n"
        "Заказ больше не отображается в вашем разделе «Мои заказы».",
        reply_markup=main_menu()
    )

    # Уведомление админу.
    try:
        sender_chat = bot.get_chat(sender_id)
        sender_username = (
            f"@{sender_chat.username}" if sender_chat.username else f"ID {sender_id}"
        )
        bot.send_message(
            ADMIN_ID,
            f"📤 <b>Передача аккаунта #{order_id}</b>\n\n"
            f"👤 Отправитель: {sender_username}\n"
            f"🎁 Получатель: {target_username}\n"
            f"📱 <code>{phone or 'не указан'}</code>"
        )
    except Exception:
        pass

