@bot.message_handler(
    func=lambda m: m.from_user.id == ADMIN_ID
    and m.from_user.id in admin_state
    and admin_state[m.from_user.id].get("step") == "add_mod"
)
def add_moderator_step(message):
    inp = (message.text or "").strip()

    if inp.upper() == "ОТМЕНА":
        admin_state.pop(message.from_user.id, None)
        bot.send_message(message.chat.id, "❌ Добавление отменено.", reply_markup=admin_menu())
        return

    try:
        user_id = int(inp)
        if user_id <= 0:
            raise ValueError
    except ValueError:
        bot.send_message(message.chat.id, "❌ Неверный Telegram ID. Пример: <code>123456789</code>")
        return

    if user_id == ADMIN_ID:
        bot.send_message(message.chat.id, "❌ Главный администратор уже имеет полный доступ.")
        return

    if is_moderator(user_id):
        bot.send_message(message.chat.id, "⚠️ Этот пользователь уже является модератором.")
        return

    add_moderator(user_id, message.from_user.id)
    admin_state.pop(message.from_user.id, None)

    bot.send_message(
        message.chat.id,
        f"✅ <b>Модератор добавлен</b>\n\n"
        f"👤 ID: <code>{user_id}</code>",
        reply_markup=admin_menu()
    )

    try:
        kb = types.InlineKeyboardMarkup()
        kb.add(types.InlineKeyboardButton("👮 Панель модератора", callback_data="moderator_panel"))
        bot.send_message(
            user_id,
            "👮 <b>Вам выдан доступ модератора.</b>\n\n"
            "Теперь доступна панель модератора.",
            reply_markup=kb
        )
    except Exception:
        pass

@bot.callback_query_handler(func=lambda call: call.data.startswith("remove_mod:"))
def remove_moderator_cb(call):
    if call.from_user.id != ADMIN_ID:
        bot.answer_callback_query(call.id, "⛔ Доступ запрещён!", show_alert=True)
        return

    try:
        mod_id = int(call.data.split(":", 1)[1])
    except (ValueError, IndexError):
        bot.answer_callback_query(call.id, "❌ Некорректный ID.", show_alert=True)
        return

    remove_mod(mod_id)
    bot.answer_callback_query(call.id, f"✅ Модератор {mod_id} удалён.")
    admin_moderators(call)

