@bot.callback_query_handler(func=lambda call: call.data == "admin_promo_create")
def admin_promo_create(call):
    if call.from_user.id != ADMIN_ID:
        bot.answer_callback_query(call.id, "⛔ Доступ запрещён!", show_alert=True)
        return
    bot.answer_callback_query(call.id)
    msg = bot.send_message(
        call.message.chat.id,
        "➕ <b>Создание промокода</b>\n\n"
        "Отправьте в одном сообщении:\n"
        "<code>КОД СКИДКА_В_ПРОЦЕНТАХ ЛИМИТ</code>\n\n"
        "Пример:\n<code>START10 10 100</code>\n"
        "Лимит <code>0</code> = без ограничений.",
        parse_mode="HTML"
    )
    bot.register_next_step_handler(msg, process_admin_promo_create)

def process_admin_promo_create(message):
    if message.from_user.id != ADMIN_ID:
        return
    parts = (message.text or "").strip().upper().split()
    if len(parts) != 3:
        bot.send_message(message.chat.id, "❌ Формат: <code>КОД СКИДКА ЛИМИТ</code>", parse_mode="HTML")
        return
    code = parts[0]
    try:
        discount = float(parts[1])
        max_uses = int(parts[2])
    except ValueError:
        bot.send_message(message.chat.id, "❌ Скидка и лимит должны быть числами.")
        return
    if not re.fullmatch(r"[A-ZА-ЯЁ0-9_-]{3,32}", code):
        bot.send_message(message.chat.id, "❌ Код: 3–32 символа, только буквы, цифры, _ или -.")
        return
    if not (0 < discount <= 100) or max_uses < 0:
        bot.send_message(message.chat.id, "❌ Скидка должна быть от 0 до 100%, лимит — от 0.")
        return
    with db_lock:
        cur.execute("""
            INSERT INTO promo_codes(code, discount_percent, max_uses, used_count, active, created)
            VALUES (?, ?, ?, 0, 1, ?)
            ON CONFLICT(code) DO UPDATE SET
                discount_percent=excluded.discount_percent,
                max_uses=excluded.max_uses,
                active=1
        """, (code, discount, max_uses, int(time.time())))
        conn.commit()
    bot.send_message(message.chat.id, f"✅ Промокод <code>{code}</code> создан: скидка <b>{discount:g}%</b>.", parse_mode="HTML", reply_markup=admin_menu())

@bot.callback_query_handler(func=lambda call: call.data == "admin_promo_disable")
def admin_promo_disable(call):
    if call.from_user.id != ADMIN_ID:
        bot.answer_callback_query(call.id, "⛔ Доступ запрещён!", show_alert=True)
        return
    bot.answer_callback_query(call.id)
    msg = bot.send_message(call.message.chat.id, "🗑 Введите код промокода, который нужно отключить:")
    bot.register_next_step_handler(msg, process_admin_promo_disable)

def process_admin_promo_disable(message):
    if message.from_user.id != ADMIN_ID:
        return
    code = (message.text or "").strip().upper()
    with db_lock:
        cur.execute("UPDATE promo_codes SET active=0 WHERE code=?", (code,))
        changed = cur.rowcount
        conn.commit()
    bot.send_message(
        message.chat.id,
        "✅ Промокод отключён." if changed else "❌ Такой промокод не найден.",
        reply_markup=admin_menu()
    )

