@bot.callback_query_handler(func=lambda call: call.data == "admin_failures")
def admin_failures(call):
    if call.from_user.id != ADMIN_ID:
        bot.answer_callback_query(call.id, "⛔ Доступ запрещён!", show_alert=True)
        return
    import html as _html
    with db_lock:
        cur.execute("SELECT COUNT(*) FROM purchase_failures")
        total = cur.fetchone()[0]
        cur.execute("SELECT ts, user_id, country_key, stage, details FROM purchase_failures "
                    "ORDER BY id DESC LIMIT 6")
        rows = cur.fetchall()
    if not rows:
        text = "🛠 <b>СБОИ ПОКУПОК</b>\n\nСбоев пока нет ✅"
    else:
        parts = [f"🛠 <b>СБОИ ПОКУПОК</b> (всего: {total}, показаны последние {len(rows)})\n"]
        for ts, uid, ck, stage, details in rows:
            when = time.strftime("%d.%m %H:%M:%S", time.localtime(ts))
            parts.append(
                f"━━━━━━━━━━\n"
                f"🕒 {when} · 👤 <code>{uid}</code> · {_html.escape(str(ck or ''))}\n"
                f"❗ <b>{_html.escape(str(stage or ''))}</b>\n"
                f"<code>{_html.escape(str(details or '')[:350])}</code>"
            )
        text = "\n".join(parts)
        if len(text) > 3900:
            text = text[:3900] + "…"
    _admin_edit(call, text, _failures_keyboard())
    try:
        bot.answer_callback_query(call.id)
    except Exception:
        pass

