@bot.message_handler(func=lambda m: m.from_user.id == ADMIN_ID and m.from_user.id in admin_state and admin_state[m.from_user.id]["step"] == "send_message")
def admin_send_message(message):
    if message.text.upper() == "ОТМЕНА":
        del admin_state[message.from_user.id]
        bot.send_message(message.chat.id, "❌ Рассылка отменена.", reply_markup=admin_menu())
        return
    users = get_all_users()
    success = fail = 0
    bot.send_message(message.chat.id, f"📨 Рассылка... Всего: <b>{len(users)}</b>")
    for uid in users:
        try:
            bot.send_message(uid, message.text)
            success += 1
            time.sleep(0.05)
        except:
            fail += 1
    del admin_state[message.from_user.id]
    bot.send_message(message.chat.id, f"✅ Рассылка завершена!\n✅ Доставлено: <b>{success}</b>\n❌ Не доставлено: <b>{fail}</b>", reply_markup=admin_menu())

