# -*- coding: utf-8 -*-
"""
Веб-версия магазина. Работает в одном процессе с ботом и на той же базе shop.db:
баланс, заказы, промокоды и платежи общие. Файл бота не изменяется.

Запуск вместе с ботом:  python run.py
"""
import hashlib
import logging
import os
import random
import re
import secrets
import threading
import time
from functools import wraps

from flask import Flask, jsonify, request, send_from_directory, session

shop = sys.modules[__name__]
log = logging.getLogger("web")

SHOP_NAME = os.environ.get("SHOP_NAME", "FizShop")
BOT_USERNAME = os.environ.get("BOT_USERNAME", "ShopAnerhanovaBot").lstrip("@")
USDT_RATE = float(os.environ.get("WEB_USDT_RATE", "1"))  # сколько ₽ зачислять за 1 USDT (как в боте — 1:1)
STATIC_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "web", "static")

app = Flask(__name__, static_folder=None)
app.config.update(
    SECRET_KEY=os.environ.get("WEB_SECRET")
    or hashlib.sha256(("web:" + str(shop.BOT_TOKEN)).encode()).hexdigest(),
    SESSION_COOKIE_HTTPONLY=True,
    SESSION_COOKIE_SAMESITE="Lax",
    SESSION_COOKIE_SECURE=os.environ.get("WEB_SECURE_COOKIE", "0") == "1",
    PERMANENT_SESSION_LIFETIME=60 * 60 * 24 * 30,
    MAX_CONTENT_LENGTH=64 * 1024,
)

db_lock, cur, conn = shop.db_lock, shop.cur, shop.conn

# ---------------------------------------------------------------- утилиты


def q(sql, args=(), one=False):
    with db_lock:
        cur.execute(sql, args)
        rows = cur.fetchall()
    return (rows[0] if rows else None) if one else rows


def ex(sql, args=()):
    with db_lock:
        cur.execute(sql, args)
        conn.commit()
        return cur.lastrowid


def ok(**kw):
    return jsonify(ok=True, **kw)


def fail(msg, code=400, **kw):
    return jsonify(ok=False, error=msg, **kw), code


def tg_send(user_id, text):
    try:
        shop.bot.send_message(user_id, text, parse_mode="HTML")
        return True
    except Exception as e:
        log.warning("tg_send %s: %s", user_id, e)
        return False


def notify_admin(text):
    tg_send(shop.ADMIN_ID, text)


def uid():
    return session.get("uid")


def is_admin(u=None):
    value = u if u is not None else uid()
    try:
        return int(value) == int(shop.ADMIN_ID)
    except (TypeError, ValueError):
        return False


def login_required(fn):
    @wraps(fn)
    def w(*a, **kw):
        if not uid():
            return fail("Войдите в аккаунт", 401)
        return fn(*a, **kw)
    return w


def admin_required(fn):
    @wraps(fn)
    def w(*a, **kw):
        if not is_admin():
            return fail("Нет доступа", 403)
        return fn(*a, **kw)
    return w


@app.before_request
def _csrf_guard():
    # JSON-запросы нельзя отправить со стороннего сайта без CORS — этого достаточно как защиты от CSRF.
    if request.method in ("POST", "PUT", "DELETE") and not request.is_json:
        return fail("Ожидается JSON", 415)


_rl = {}
_rl_lock = threading.Lock()


def rate_limit(key, limit, window):
    now = time.time()
    with _rl_lock:
        arr = [t for t in _rl.get(key, []) if now - t < window]
        if len(arr) >= limit:
            _rl[key] = arr
            return False
        arr.append(now)
        _rl[key] = arr
    return True


def ip():
    return (request.headers.get("X-Forwarded-For", request.remote_addr) or "?").split(",")[0].strip()


def body():
    return request.get_json(silent=True) or {}


def fmt_money(x):
    return round(float(x), 2)


# ---------------------------------------------------------------- данные магазина


def country(key):
    info = shop.get_country_info(key)
    if not info:
        return None
    flag, name, prefix, pmin, pmax, price, lzt = info
    return dict(key=key, flag=flag, name=name, prefix=prefix, price=price,
                cc=key.lower(), lzt=lzt, pmin=pmin, pmax=pmax)


def user_promo(u):
    p = shop.get_user_promo(u)
    return {"code": p["code"], "discount": p["discount"]} if p else None


def final_price(price, promo):
    return round(price * (1 - promo["discount"] / 100), 2) if promo else price


def order_label(o_country):
    c = country(o_country) if o_country else None
    return c


def order_dict(r):
    oid, price, status, created, ckey, phone, item_id = r
    c = country(ckey) if ckey else None
    has_review = bool(q("SELECT 1 FROM reviews WHERE order_id=?", (oid,), one=True))
    return dict(
        id=oid, price=fmt_money(price), status=status, created=created,
        country=({k: c[k] for k in ("key", "name", "prefix", "cc")} if c else None),
        phone=phone or "", can_sms=bool(status == "completed" and item_id),
        reviewed=has_review,
    )


# ---------------------------------------------------------------- страницы


@app.get("/")
def index():
    return send_from_directory(STATIC_DIR, "index.html")


@app.get("/static/<path:p>")
def static_files(p):
    r = send_from_directory(STATIC_DIR, p)
    r.headers["Cache-Control"] = "no-cache"
    return r


# ---------------------------------------------------------------- вход через бота

_codes = {}  # user_id -> dict(code, exp, tries)
_codes_lock = threading.Lock()


@app.post("/api/auth/code")
def auth_code():
    d = body()
    try:
        u = int(str(d.get("user_id", "")).strip())
        assert 0 < u < 10 ** 13
    except Exception:
        return fail("Введите числовой Telegram ID. Он указан в боте: Профиль → ID.")
    if not rate_limit("code-ip:" + ip(), 8, 600) or not rate_limit(f"code-u:{u}", 3, 300):
        return fail("Слишком много попыток. Подождите пару минут.", 429)
    code = "".join(random.choice("0123456789") for _ in range(6))
    sent = tg_send(u, f"🔐 <b>Вход на сайт {SHOP_NAME}</b>\n\nКод: <code>{code}</code>\n"
                      f"Действует 5 минут. Если это были не вы — просто проигнорируйте сообщение.")
    if not sent:
        return fail(f"Не удалось отправить код. Откройте бота @{BOT_USERNAME}, нажмите /start и повторите.", 422,
                    bot=BOT_USERNAME)
    with _codes_lock:
        _codes[u] = dict(code=code, exp=time.time() + 300, tries=0)
    return ok()


@app.post("/api/auth/verify")
def auth_verify():
    d = body()
    try:
        u = int(str(d.get("user_id", "")).strip())
    except Exception:
        return fail("Некорректный ID")
    code = re.sub(r"\D", "", str(d.get("code", "")))
    with _codes_lock:
        rec = _codes.get(u)
        if not rec or rec["exp"] < time.time():
            return fail("Код устарел. Запросите новый.")
        rec["tries"] += 1
        if rec["tries"] > 5:
            _codes.pop(u, None)
            return fail("Слишком много неверных попыток. Запросите новый код.")
        if not secrets.compare_digest(rec["code"], code):
            return fail("Неверный код")
        _codes.pop(u, None)
    shop.add_user(u)
    session.clear()
    session.permanent = True
    session["uid"] = u
    return ok()


@app.post("/api/auth/logout")
def auth_logout():
    session.clear()
    return ok()


# ---------------------------------------------------------------- профиль и каталог


@app.get("/api/config")
def api_config():
    sold = q("SELECT COUNT(*) FROM orders WHERE status='completed' AND country_key!=''", one=True)[0]
    reviews = q("SELECT COUNT(*) FROM reviews", one=True)[0]
    return ok(name=SHOP_NAME, bot=BOT_USERNAME, support=shop.ADMIN_USERNAME,
              sold=sold, reviews=reviews, countries=len(shop.CATALOG),
              min_sbp=shop.MIN_DEPOSIT_SBP, min_usdt=shop.MIN_DEPOSIT_CRYPTO,
              sbp=bool(shop.PLATEGA_MERCHANT_ID and shop.PLATEGA_SECRET),
              usdt=bool(shop.CRYPTO_PAY_TOKEN), usdt_rate=USDT_RATE)


@app.get("/api/me")
def api_me():
    u = uid()
    if not u:
        return ok(user=None)
    n = q("SELECT COUNT(*) FROM orders WHERE user_id=?", (u,), one=True)[0]
    return ok(user=dict(id=u, balance=fmt_money(shop.get_balance(u)), orders=n,
                        promo=user_promo(u), admin=is_admin(u),
                        mod=bool(shop.is_moderator(u))))


@app.get("/api/catalog")
def api_catalog():
    promo = user_promo(uid()) if uid() else None
    items = []
    for key in shop.CATALOG:
        c = country(key)
        items.append(dict(key=key, name=c["name"], prefix=c["prefix"], cc=c["cc"],
                          price=c["price"], final=final_price(c["price"], promo)))
    return ok(items=items, promo=promo)


@app.get("/api/boxes")
def api_boxes():
    boxes = []
    for key, (emoji, name, price, prizes) in shop.CASES.items():
        total = sum(w for _, w in prizes)
        lst = []
        for ck, w in prizes:
            c = country(ck)
            if c:
                lst.append(dict(key=ck, name=c["name"], prefix=c["prefix"], cc=c["cc"],
                                chance=round(w * 100 / total, 1)))
        lst.sort(key=lambda x: -x["chance"])
        boxes.append(dict(key=key, emoji=emoji, name=name, price=price, prizes=lst))
    return ok(boxes=boxes)


# ---------------------------------------------------------------- покупка аккаунта

_jobs = {}
_jobs_lock = threading.Lock()
_busy = set()


def _job_set(jid, **kw):
    with _jobs_lock:
        _jobs.setdefault(jid, {}).update(kw)


def _log_failure(u, ckey, stage, data, c):
    log.error("PURCHASE FAIL [%s] user=%s %s: %s", stage, u, ckey, str(data)[:500])
    try:
        with db_lock:
            cur.execute(
                "INSERT INTO purchase_failures (ts,user_id,country_key,stage,details) VALUES (?,?,?,?,?)",
                (int(time.time()), u, ckey, "WEB " + stage,
                 f"LZT: {c['lzt']}, {c['pmin']}-{c['pmax']} ₽\n{str(data)[:1500]}"))
            cur.execute("DELETE FROM purchase_failures WHERE id NOT IN "
                        "(SELECT id FROM purchase_failures ORDER BY id DESC LIMIT 200)")
            conn.commit()
    except Exception as e:
        log.error("failure log: %s", e)


def run_purchase(jid, u, ckey):
    """Та же логика, что в боте (_process_lolz_purchase), но результат идёт в веб, а не в чат."""
    c = country(ckey)
    promo = user_promo(u)
    price = final_price(c["price"], promo)

    def err(msg):
        _job_set(jid, status="error", error=msg)

    try:
        _job_set(jid, step="search")
        res = shop.lzt_search(c["lzt"], c["pmin"], c["pmax"])
        if not res or not res.get("items"):
            _log_failure(u, ckey, "ПОИСК", shop.LZT_LAST_ERROR or res, c)
            return err("Аккаунты этой страны временно закончились. Попробуйте через несколько минут.")
        items = [i for i in res["items"] if i.get("item_id") and shop.is_clean_account(i)]
        if not items:
            _log_failure(u, ckey, "ФИЛЬТР", [(i.get("item_id"), i.get("origin")) for i in res["items"]], c)
            return err("Подходящих аккаунтов не нашлось. Попробуйте позже.")

        _job_set(jid, step="check")
        valid, log_lines = None, []
        for it in items:
            chk = shop.lzt_check(it["item_id"])
            if shop.lzt_check_ok(chk):
                valid = it
                break
            log_lines.append(f"#{it['item_id']}: {str(chk)[:200]}")
        if not valid:
            _log_failure(u, ckey, "CHECK", "\n".join(log_lines), c)
            return err("Не нашли валидный аккаунт. Попробуйте позже.")

        target_id = valid["item_id"]
        fallback = valid.get("telegram_phone") or valid.get("title") or f"Telegram #{target_id}"
        try:
            target_price = float(valid.get("price", 0))
        except Exception:
            target_price = 0.0
        if target_price <= 0 or target_price >= price:
            log.error("Цена LZT %s >= цена продажи %s (#%s)", target_price, price, target_id)
            return err("Аккаунты временно недоступны. Попробуйте позже.")

        # резерв денег (атомарно) — как в боте
        with db_lock:
            cur.execute("UPDATE users SET balance=balance-? WHERE user_id=? AND balance>=?", (price, u, price))
            if cur.rowcount != 1:
                conn.rollback()
                return err("Недостаточно средств на балансе.")
            conn.commit()

        def refund():
            ex("UPDATE users SET balance=balance+? WHERE user_id=?", (price, u))

        _job_set(jid, step="buy")
        try:
            buy = shop.lzt_buy(target_id, target_price)
        except Exception as e:
            log.error("lzt_buy: %s", e)
            buy = None
        if not buy or buy.get("errors") or buy.get("error"):
            refund()
            _log_failure(u, ckey, "FAST-BUY", buy, c)
            return err("Не удалось оформить покупку. Деньги не списаны.")

        try:
            phone = shop.lzt_get_phone(target_id) or str(fallback)
        except Exception:
            phone = str(fallback)

        oid = 0
        try:
            with db_lock:
                cur.execute("""INSERT INTO orders (user_id,product_id,item_id,price,status,created,country_key,lolz_item_id,phone)
                               VALUES (?,0,0,?,'completed',?,?,?,?)""",
                            (u, price, int(time.time()), ckey, str(target_id), phone))
                oid = cur.lastrowid
                cur.execute("""INSERT INTO lolz_purchases (user_id,item_id,title,price_lolz,price_bot,status,timestamp)
                               VALUES (?,?,?,?,?,'success',?)""",
                            (u, str(target_id), phone, target_price, price, str(int(time.time()))))
                if promo:
                    cur.execute("INSERT OR IGNORE INTO promo_uses (code,user_id,created) VALUES (?,?,?)",
                                (promo["code"], u, int(time.time())))
                    cur.execute("UPDATE promo_codes SET used_count=used_count+1 WHERE code=?", (promo["code"],))
                    cur.execute("UPDATE users SET promo_code='' WHERE user_id=?", (u,))
                conn.commit()
        except Exception as e:
            conn.rollback()
            log.error("DB после покупки: %s", e)
            notify_admin(f"⚠️ Веб: ошибка записи заказа после покупки!\nuser={u}\nLZT={target_id}\n"
                         f"phone={phone}\nсписано={price}\n{e}")

        _job_set(jid, status="done", step="done",
                 result=dict(order_id=oid, phone=phone, price=price, balance=fmt_money(shop.get_balance(u)),
                             country=dict(name=c["name"], prefix=c["prefix"], cc=c["cc"])))
        tg_send(u, f"✅ <b>Аккаунт куплен на сайте</b>\n\n🌍 {c['flag']} {c['name']}\n📱 <code>{phone}</code>\n"
                   f"💸 {price:g} ₽\n\nКод входа можно получить на сайте или в боте: «Заказы».")
        notify_admin(f"🌐 <b>Продажа с сайта #{oid}</b>\n👤 ID {u}\n🌍 {c['flag']} {c['name']}\n"
                     f"📱 <code>{phone}</code>\n💰 {price:g} ₽ (закупка {target_price:g} ₽)")
    except Exception as e:
        log.exception("run_purchase")
        err("Внутренняя ошибка. Если деньги списались — напишите в поддержку.")
    finally:
        with _jobs_lock:
            _busy.discard(u)


@app.post("/api/buy")
@login_required
def api_buy():
    ckey = str(body().get("country", ""))
    c = country(ckey) if ckey in shop.CATALOG else None
    if not c:
        return fail("Неизвестная страна")
    u = uid()
    price = final_price(c["price"], user_promo(u))
    bal = shop.get_balance(u)
    if bal < price:
        return fail("Недостаточно средств", 402, need=fmt_money(price - bal), price=price)
    with _jobs_lock:
        if u in _busy:
            return fail("Предыдущая покупка ещё выполняется", 409)
        _busy.add(u)
        # чистим старые задачи
        now = time.time()
        for k in [k for k, v in _jobs.items() if now - v.get("t", now) > 900]:
            _jobs.pop(k, None)
    jid = secrets.token_urlsafe(12)
    _job_set(jid, status="running", step="start", user=u, t=time.time())
    threading.Thread(target=run_purchase, args=(jid, u, ckey), daemon=True).start()
    return ok(job=jid)


@app.get("/api/job/<jid>")
@login_required
def api_job(jid):
    with _jobs_lock:
        j = dict(_jobs.get(jid) or {})
    if not j or j.get("user") != uid():
        return fail("Задача не найдена", 404)
    return ok(status=j.get("status"), step=j.get("step"), error=j.get("error"), result=j.get("result"))


