# ---------------------------------------------------------------- пополнение


def _credit_once(payment_id, user, amount):
    """Атомарно: помечаем платёж оплаченным и зачисляем только один раз (бот и сайт делят таблицу payments)."""
    with db_lock:
        cur.execute("UPDATE payments SET status='paid' WHERE payment_id=? AND status!='paid'", (payment_id,))
        if cur.rowcount != 1:
            conn.rollback()
            return False
        cur.execute("UPDATE users SET balance=balance+? WHERE user_id=?", (amount, user))
        conn.commit()
    return True


