@app.post("/api/deposit/check")
@login_required
def dep_check():
    pid = str(body().get("payment_id", ""))
    row = q("SELECT user_id,amount,currency,status FROM payments WHERE payment_id=?", (pid,), one=True)
    if not row or int(row[0]) != uid():
        return fail("Платёж не найден", 404)
    user, amount, cur_, status = row
    if status == "paid":
        return ok(status="paid", balance=fmt_money(shop.get_balance(uid())))
    if cur_ == shop.CRYPTO_ASSET:
        invs = shop.crypto_api("getInvoices", {"invoice_ids": pid})
        if not invs:
            return fail("Не удалось проверить платёж", 502)
        if invs[0].get("status") != "paid":
            return ok(status="pending")
        credit = float(invs[0]["amount"]) * USDT_RATE
    else:
        res = shop.platega_api("GET", f"/transaction/{pid}")
        if not isinstance(res, dict):
            return fail("Не удалось проверить платёж", 502)
        st = str(res.get("status") or "").upper()
        if st in ("CANCELED", "CHARGEBACKED"):
            return ok(status="canceled")
        if st != "CONFIRMED":
            return ok(status="pending")
        credit = float(amount)
    if _credit_once(pid, uid(), credit):
        tg_send(uid(), f"✅ <b>Оплата получена (сайт)</b>\n💰 Зачислено: <b>{credit:.2f} ₽</b>\n"
                       f"💳 Баланс: <b>{shop.get_balance(uid()):.2f} ₽</b>")
    return ok(status="paid", balance=fmt_money(shop.get_balance(uid())))


