@app.get("/api/admin/stats")
@admin_required
def adm_stats():
    one = lambda s, a=(): q(s, a, one=True)[0]
    day = int(time.time()) - 86400
    revenue = one("SELECT COALESCE(SUM(price),0) FROM orders WHERE status='completed'")
    cost = one("SELECT COALESCE(SUM(price_lolz),0) FROM lolz_purchases WHERE status='success'")
    # выручка по дням за 14 дней
    days = []
    for i in range(13, -1, -1):
        a = int(time.time() // 86400 * 86400) - i * 86400
        days.append(dict(day=time.strftime("%d.%m", time.localtime(a)),
                         sum=fmt_money(one("SELECT COALESCE(SUM(price),0) FROM orders WHERE status='completed' "
                                           "AND created>=? AND created<?", (a, a + 86400)))))
    top = q("""SELECT country_key,COUNT(*) c FROM orders WHERE status='completed' AND country_key!=''
               GROUP BY country_key ORDER BY c DESC LIMIT 5""")
    return ok(users=one("SELECT COUNT(*) FROM users"),
              balances=fmt_money(one("SELECT COALESCE(SUM(balance),0) FROM users")),
              orders=one("SELECT COUNT(*) FROM orders"),
              pending=one("SELECT COUNT(*) FROM orders WHERE status='pending'"),
              revenue=fmt_money(revenue), cost=fmt_money(cost), profit=fmt_money(revenue - cost),
              today=fmt_money(one("SELECT COALESCE(SUM(price),0) FROM orders WHERE status='completed' AND created>=?", (day,))),
              days=days,
              top=[dict(key=k, name=(country(k) or {}).get("name", k), cc=k.lower(), n=n) for k, n in top])


